CREATE INDEX IF NOT EXISTS idx_idempotency_records_list
	ON idempotency_records (expires_at_ns, created_at_ns DESC, id DESC);

CREATE TABLE IF NOT EXISTS idempotency_conflict_events (
	id                           TEXT PRIMARY KEY,
